-- Cadastro de Empregadores (lista suja do trabalho escravo, MTE) como ESPELHO VERSIONADO: tabular.mte_cadastro_empregadores. Idempotente.
-- Rodar como postgres (o etl so tem DML):
--   .\infra\scripts\dw.ps1 psql -Arquivo mte\cadastro_empregadores\sql\01_tabela.sql
--
-- Tabela SEM geometria (a fonte so traz o endereco do estabelecimento em texto). Uma linha por empregador/acao fiscal/estabelecimento. A lista e semestral e o MTE
-- retira os nomes ao fim de 2 anos: o que a edicao nova nao traz tem a versao FECHADA (vigente_ate); "esta na lista hoje" = vigente_ate IS NULL.
-- O ID do arquivo e apenas a ordem da linha na edicao (muda entre edicoes): chave_linha = identidade (documento, ano da acao fiscal, estabelecimento) + ordinal nos identicos.
-- DADO PESSOAL (mesma decisao do IBAMA): a lista e publica por lei (Portaria Interministerial 18/2024); nome como a fonte publica; CPF de pessoa fisica NAO e guardado,
-- so o HMAC-SHA256 (dwlib/documento.py, mesma chave do IBAMA); CNPJ como vem.

INSERT INTO dim.fontes (nome, sigla, url, descricao)
SELECT 'MTE', 'MTE', 'https://www.gov.br/trabalho-e-emprego', 'Ministerio do Trabalho e Emprego (Cadastro de Empregadores, a lista suja do trabalho escravo)'
WHERE NOT EXISTS (SELECT 1 FROM dim.fontes WHERE nome = 'MTE');

CREATE TABLE IF NOT EXISTS tabular.mte_cadastro_empregadores (
    id                            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    chave_linha                   text        NOT NULL,   -- derivado: identidade do registro (o ID do arquivo nao e estavel); ver LEIAME
    id_arquivo                    integer,                -- fonte: ID (ordem da linha na edicao; nao entra na comparacao)
    ano_acao_fiscal               smallint,               -- fonte: Ano da acao fiscal
    uf                            text,                   -- fonte: UF
    id_estado                     smallint    REFERENCES dim.estados (id_estado),   -- derivado de uf
    empregador                    text,                   -- fonte: Empregador (nome ou razao social; dado pessoal como a fonte publica)
    cpf_cnpj                      text,                   -- fonte: CNPJ/CPF. CPF de pessoa fisica NAO e guardado (NULL); CNPJ (so digitos) entra como vem
    tipo_doc_empregador           text,                   -- derivado: CPF, CNPJ, OUTRO ou NULL
    doc_valido                    boolean,                -- derivado: digitos verificadores conferem
    cpf_empregador_hash           text,                   -- derivado: HMAC-SHA256 dos 11 digitos do CPF (so se tipo = CPF); mesma chave do IBAMA, do ICMBio e da SEMA-MT
    estabelecimento               text,                   -- fonte: Estabelecimento (endereco do local da fiscalizacao)
    trabalhadores_envolvidos      integer,                -- fonte: Trabalhadores envolvidos
    cnae                          text,                   -- fonte: CNAE (atividade economica)
    decisao_administrativa        text,                   -- fonte: Decisao administrativa de procedencia (data DD/MM/AAAA)
    decisao_administrativa_data   date,                   -- derivado: decisao_administrativa como date
    inclusao_cadastro             text,                   -- fonte: Inclusao no Cadastro de Empregadores (data DD/MM/AAAA; pode ser lista de datas e periodos)
    inclusao_cadastro_data        date,                   -- derivado: ultima data encontrada em inclusao_cadastro
    id_fonte                      smallint    NOT NULL REFERENCES dim.fontes (id_fonte),
    importado_em                  date        NOT NULL DEFAULT current_date,
    vigente_desde                 date        NOT NULL DEFAULT current_date,
    vigente_ate                   date,
    coletado_em                   timestamptz NOT NULL DEFAULT now(),
    reaberto_em                   date
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_mte_empregadores_vigente ON tabular.mte_cadastro_empregadores (chave_linha) WHERE vigente_ate IS NULL;
CREATE INDEX IF NOT EXISTS ix_mte_empregadores_hash ON tabular.mte_cadastro_empregadores (cpf_empregador_hash) WHERE vigente_ate IS NULL AND cpf_empregador_hash IS NOT NULL;
CREATE INDEX IF NOT EXISTS ix_mte_empregadores_cnpj ON tabular.mte_cadastro_empregadores (cpf_cnpj) WHERE vigente_ate IS NULL AND cpf_cnpj IS NOT NULL;

COMMENT ON TABLE tabular.mte_cadastro_empregadores IS
    'Cadastro de Empregadores do MTE (lista suja do trabalho escravo). Sem geometria. Espelho versionado: vigente = esta na lista hoje. Dado pessoal: CPF so como HMAC. Ver mte/cadastro_empregadores/LEIAME_cadastro_empregadores.md.';
COMMENT ON COLUMN tabular.mte_cadastro_empregadores.chave_linha IS 'Derivado: identidade = documento (hash do CPF ou CNPJ)|ano da acao fiscal|estabelecimento (+ ordinal se identicos).';
COMMENT ON COLUMN tabular.mte_cadastro_empregadores.cpf_cnpj IS 'Origem: CNPJ/CPF. CPF de pessoa fisica nao e guardado (NULL; ver cpf_empregador_hash).';

INSERT INTO catalogo.mapa_colunas (tabela, coluna, origem, fonte, observacao)
SELECT 'tabular.mte_cadastro_empregadores', c.column_name,
       CASE WHEN c.column_name IN ('chave_linha','id_estado','tipo_doc_empregador','doc_valido','cpf_empregador_hash','decisao_administrativa_data','inclusao_cadastro_data') THEN 'derivado'
            WHEN c.column_name IN ('id','id_fonte','importado_em','vigente_desde','vigente_ate','coletado_em','reaberto_em') THEN 'controle'
            WHEN c.column_name = 'id_arquivo' THEN 'ID' WHEN c.column_name = 'ano_acao_fiscal' THEN 'Ano da ação fiscal' WHEN c.column_name = 'cpf_cnpj' THEN 'CNPJ/CPF'
            WHEN c.column_name = 'trabalhadores_envolvidos' THEN 'Trabalhadores envolvidos' WHEN c.column_name = 'decisao_administrativa' THEN 'Decisão administrativa de procedência'
            WHEN c.column_name = 'inclusao_cadastro' THEN 'Inclusão no Cadastro de Empregadores' ELSE initcap(c.column_name) END,
       CASE WHEN c.column_name IN ('chave_linha','id_estado','tipo_doc_empregador','doc_valido','cpf_empregador_hash','decisao_administrativa_data','inclusao_cadastro_data','id','id_fonte',
                                   'importado_em','vigente_desde','vigente_ate','coletado_em','reaberto_em') THEN 'pipeline' ELSE 'MTE' END,
       CASE WHEN c.column_name = 'id_estado' THEN 'dim.estados' WHEN c.column_name = 'cpf_empregador_hash' THEN 'HMAC-SHA256 com a mesma chave do IBAMA' END
FROM information_schema.columns c
WHERE c.table_schema = 'tabular' AND c.table_name = 'mte_cadastro_empregadores'
ON CONFLICT (tabela, coluna) DO UPDATE SET origem = EXCLUDED.origem, fonte = EXCLUDED.fonte;

GRANT SELECT, INSERT, UPDATE, DELETE ON tabular.mte_cadastro_empregadores TO etl;      -- DELETE: so para a rotina de retencao
GRANT SELECT ON tabular.mte_cadastro_empregadores TO leitura, geoserver, analistas;
GRANT MAINTAIN ON tabular.mte_cadastro_empregadores TO etl;

SELECT 'tabular.mte_cadastro_empregadores' AS item, count(*)::text AS valor FROM tabular.mte_cadastro_empregadores;
